<template><div v-if="event" class="demo-widget alert-widget" :style="widgetStyle(widget.settings)"><span class="widget-kicker">{{ runtimeMode === 'browser-source' ? 'STREAM ALERT' : 'SIMULATED ALERT' }}</span><b>{{ headline }}</b><p>{{ detail }}</p></div></template>
<script setup>import { computed } from 'vue'; import { widgetStyle,useWidgetEvents } from '../../widgetHelpers.js'; const props=defineProps({widget:{type:Object,required:true},runtimeMode:{type:String,default:'editor-preview'}}); const event=useWidgetEvents(props.widget,props.runtimeMode==='browser-source'?null:{topic:'stream.follow',actor:{displayName:'NovaRespawn'},payload:{}}); const headline=computed(()=>({ 'stream.follow':'New follower!', 'stream.subscription':'New subscriber!', 'stream.cheer':'Cheer received!', 'stream.raid':'Raid incoming!', 'reward.redeemed':'Reward redeemed!' }[event.value?.topic]||'Stream alert')); const detail=computed(()=>`${event.value?.actor?.displayName||'A community member'} ${event.value?.topic==='stream.raid'?`arrived with ${event.value?.payload?.viewers||0} viewers`:'joined the moment'}`)</script>
